import { FlexCarousel } from "solen-design/react";

const items = [
  { src: "/photos/form-01.jpg", alt: "Chrome form", title: "Iridescence" },
  { src: "/photos/form-02.jpg", alt: "Clay bust", title: "Clay Study" },
  { src: "/photos/form-03.jpg", alt: "Plaster bust", title: "Plaster" }
];

<FlexCarousel
  items={items}
  preset="liquid"
  intro="rise"
  cardHeight={0.5}
  gap={12}
  radius={0}
  fit="natural"
  squeeze={0.2}
  focusOnClick={true}
  autoplay={false}
  interval={4}
  captions={true}
  captureWheel={true}
  onChange={(index, item) => console.log(index, item.title)}
/>
